/* KCNA mock bank 1: Kubernetes Fundamentals (domain 'fund'), 80 questions.
   Subtopics: Core Concepts (30) · Administration (18) · Scheduling (20) · Containerization (12). */
KS.registerMockBank('kcna', [

  // ───────────────────────── Core Concepts: architecture & components ─────────────────────────
  { domain: 'fund', q: 'A node stops sending heartbeats. Which component notices this, marks the node as not ready and eventually lets its Pods be evicted?', options: ['kube-scheduler', 'kubelet on another node', 'kube-proxy', 'The node lifecycle controller in kube-controller-manager'], answer: 3, explain: 'The <b>node lifecycle controller</b> (part of kube-controller-manager) watches node heartbeats (Lease objects and status). When they stop it sets the node condition to Unknown, adds <code>unreachable</code> taints, and taint-based eviction removes Pods after their toleration period. The scheduler only places new Pods; kubelets do not monitor each other; kube-proxy only handles Service traffic rules.', ref: 'https://kubernetes.io/docs/concepts/architecture/nodes/' },
  { domain: 'fund', q: 'In a cluster built with kubeadm, how are kube-apiserver, kube-scheduler and kube-controller-manager usually run?', options: ['As systemd services installed from distro packages', 'As a Deployment in the default namespace', 'As static Pods that the kubelet starts from manifests in /etc/kubernetes/manifests', 'As a DaemonSet scheduled on control plane nodes'], answer: 2, explain: 'kubeadm writes the control plane components as <b>static Pod</b> manifests. The kubelet watches that directory and runs them directly, without the API server or scheduler being involved (it could not depend on them, they do not exist yet). Only the kubelet and the container runtime run as systemd services. They are not Deployments or DaemonSets.', ref: 'https://kubernetes.io/docs/tasks/configure-pod-container/static-pod/' },
  { domain: 'fund', q: 'You run <code>kubectl delete pod kube-scheduler-cp1 -n kube-system</code> on a kubeadm cluster. What happens?', options: ['The scheduler is permanently removed until you run kubeadm init again', 'The Pod reappears almost immediately because it is a mirror of a static Pod whose manifest still exists on the node', 'The kube-controller-manager recreates it from a ReplicaSet', 'The command is rejected because kube-system Pods are immutable'], answer: 1, explain: 'Pods in kube-system named <code>&lt;component&gt;-&lt;node&gt;</code> are <b>mirror Pods</b>: read-only API representations of static Pods. The kubelet owns the real Pod and recreates the mirror. To really stop it you would move the manifest out of <code>/etc/kubernetes/manifests</code>. No ReplicaSet is involved and kube-system objects are not immutable.', ref: 'https://kubernetes.io/docs/tasks/configure-pod-container/static-pod/' },
  { domain: 'fund', q: 'Which mechanism makes <code>kubectl delete deployment web</code> also remove the ReplicaSets and Pods that belong to it?', options: ['The scheduler cleans up Pods whose Deployment is missing', 'kube-proxy removes endpoints, which terminates the Pods', 'The kubelet deletes Pods with a matching label', 'ownerReferences on the child objects plus the garbage collector (cascading deletion)'], answer: 3, explain: 'Each ReplicaSet carries an <b>ownerReference</b> to its Deployment and each Pod one to its ReplicaSet. The <b>garbage collector</b> in kube-controller-manager deletes dependents when the owner is gone (unless you pass <code>--cascade=orphan</code>). Labels alone do not trigger deletion, and neither the scheduler nor kube-proxy deletes objects.', ref: 'https://kubernetes.io/docs/concepts/architecture/garbage-collection/' },
  { domain: 'fund', q: '<code>kubectl get deploy web -o yaml</code> shows <code>spec.replicas: 5</code> and <code>status.readyReplicas: 3</code>. What does this tell you?', options: ['Someone manually edited status to 3, which overrides spec', 'Five Pods are desired; three are currently ready and the controllers are still working to close the gap', 'The Deployment is capped at 3 replicas by its ReplicaSet', 'Two Pods were deleted and will not come back until you re-apply the manifest'], answer: 1, explain: '<b>spec</b> is the desired state you declared; <b>status</b> is what the system observes. A gap means reconciliation is in progress (Pods starting, failing readiness, or Pending). Users do not set status, a ReplicaSet does not cap its Deployment, and missing Pods are recreated automatically.', ref: 'https://kubernetes.io/docs/concepts/overview/working-with-objects/' },

  // ───────────────────────── Core Concepts: Pods & containers ─────────────────────────
  { domain: 'fund', q: 'An application needs a helper process that reads its log files and talks to it over <code>localhost</code>. Where should the helper run?', options: ['In a separate Deployment with the same labels', 'In a DaemonSet on the same nodes', 'As an additional container in the same Pod, sharing a volume and the network namespace', 'Inside the main container, started by its entrypoint script'], answer: 2, explain: 'Containers in one <b>Pod</b> share the network namespace (same IP, reachable on localhost) and can share volumes. That is the sidecar pattern. A separate Deployment or DaemonSet gets different Pod IPs and no shared filesystem. Cramming two processes into one container breaks the one-process-per-container model and per-container health checks.', ref: 'https://kubernetes.io/docs/concepts/workloads/pods/' },
  { domain: 'fund', q: 'Which statement about init containers is correct?', options: ['They run one after another, and each must complete successfully before the app containers start', 'They run in parallel with the app containers for the life of the Pod', 'They run only once per node, regardless of how many Pods start', 'They restart the app containers when a ConfigMap changes'], answer: 0, explain: '<b>Init containers</b> run sequentially to completion before any regular container starts; if one fails, the kubelet retries it according to the Pod’s restartPolicy. Long-running helpers next to the app are sidecars, not classic init containers. Nothing about them is per-node or tied to ConfigMap changes.', ref: 'https://kubernetes.io/docs/concepts/workloads/pods/init-containers/' },
  { domain: 'fund', q: 'In Kubernetes 1.33+, how do you declare a native sidecar container that starts before the app containers and keeps running alongside them?', options: ['Add the annotation <code>sidecar.kubernetes.io/enabled: "true"</code>', 'Use a separate <code>sidecars:</code> list in the Pod spec', 'Set <code>type: Sidecar</code> on a regular container', 'Put it in <code>initContainers</code> with <code>restartPolicy: Always</code>'], answer: 3, explain: 'Native sidecars (GA in 1.33) are <b>init containers with <code>restartPolicy: Always</code></b>. They start in init order, keep running for the Pod’s lifetime, and do not block Job completion. There is no <code>sidecars:</code> field, no container <code>type</code>, and no such annotation.', ref: 'https://kubernetes.io/docs/concepts/workloads/pods/sidecar-containers/' },
  { domain: 'fund', q: 'Which TWO statements about container probes are correct? (Select 2)', options: ['A failing readiness probe causes the kubelet to restart the container', 'A failing liveness probe causes the kubelet to restart the container', 'A failing readiness probe removes the Pod from the Service’s endpoints', 'A startup probe runs continuously for the whole life of the container'], answer: [1, 2], explain: '<b>Liveness</b> failure → container restart. <b>Readiness</b> failure → Pod is marked not ready and stops receiving Service traffic, but is not restarted. A <b>startup</b> probe runs only until it first succeeds, holding off liveness and readiness checks for slow starters.', ref: 'https://kubernetes.io/docs/concepts/workloads/pods/probes/' },
  { domain: 'fund', q: 'Which of the following is a valid value of a Pod’s <code>status.phase</code>?', options: ['CrashLoopBackOff', 'ContainerCreating', 'Succeeded', 'Terminating'], answer: 2, explain: 'The Pod phases are <b>Pending, Running, Succeeded, Failed and Unknown</b>. CrashLoopBackOff and ContainerCreating are container <i>waiting reasons</i> that kubectl shows in the STATUS column, and Terminating is displayed when a deletion timestamp is set. None of them is a phase.', ref: 'https://kubernetes.io/docs/concepts/workloads/pods/pod-lifecycle/' },
  { domain: 'fund', q: 'Every container in a Pod sets CPU and memory requests equal to its CPU and memory limits. Which QoS class does the Pod get?', options: ['BestEffort', 'Burstable', 'Critical', 'Guaranteed'], answer: 3, explain: '<b>Guaranteed</b> requires requests = limits for both CPU and memory in every container. Burstable is any Pod with at least one request or limit that does not meet that rule; BestEffort sets none at all. “Critical” is not a QoS class (criticality is expressed with PriorityClasses). Guaranteed Pods are the last to be evicted under node memory pressure.', ref: 'https://kubernetes.io/docs/concepts/workloads/pods/pod-qos/' },

  // ───────────────────────── Core Concepts: workload controllers ─────────────────────────
  { domain: 'fund', q: 'You change the image of a Deployment with <code>kubectl set image deployment/web app=web:2.0</code>. What happens with the default strategy?', options: ['All existing Pods are deleted, then new ones are created', 'The existing ReplicaSet edits its Pods in place', 'Nothing happens until you run kubectl rollout restart', 'A new ReplicaSet is created and scaled up while the old one is scaled down, and the old one is kept for rollback'], answer: 3, explain: 'The default <b>RollingUpdate</b> strategy creates a new ReplicaSet for the new Pod template and shifts replicas gradually within maxSurge/maxUnavailable. The old ReplicaSet stays at 0 replicas so <code>kubectl rollout undo</code> can return to it. Delete-all-first is the <code>Recreate</code> strategy; Pods are never edited in place to change images through a ReplicaSet.', ref: 'https://kubernetes.io/docs/concepts/workloads/controllers/deployment/' },
  { domain: 'fund', q: 'A cluster runs a log collector as a DaemonSet. A new worker node joins the cluster. What happens?', options: ['Nothing until you increase the DaemonSet’s replicas field', 'The DaemonSet controller automatically creates a collector Pod on the new node', 'The scheduler moves one existing collector Pod to the new node', 'You must label the node with daemonset=true first'], answer: 1, explain: 'A <b>DaemonSet</b> ensures one Pod per eligible node, so new nodes get a Pod automatically and removed nodes have theirs garbage-collected. DaemonSets have no replicas field and Pods are never moved between nodes. A nodeSelector is only needed if you want to restrict it to a subset of nodes.', ref: 'https://kubernetes.io/docs/concepts/workloads/controllers/daemonset/' },
  { domain: 'fund', q: 'A StatefulSet named <code>db</code> runs 3 replicas and is scaled down to 2. Which Pod is removed?', options: ['A random Pod chosen by the scheduler', 'db-0, the oldest Pod', 'db-2, the highest ordinal', 'The Pod on the busiest node'], answer: 2, explain: 'StatefulSet Pods have stable ordinal names (<code>db-0</code>, <code>db-1</code>, <code>db-2</code>). With the default OrderedReady policy they are created in ascending order and removed in <b>descending</b> order, so <code>db-2</code> goes first. Deployments pick Pods to delete by other heuristics; StatefulSets never choose randomly.', ref: 'https://kubernetes.io/docs/concepts/workloads/controllers/statefulset/' },
  { domain: 'fund', q: 'Which TWO features does a StatefulSet provide that a Deployment does not? (Select 2)', options: ['A stable, ordinal Pod name and network identity that survives rescheduling', 'Automatic horizontal scaling based on CPU usage', 'Rolling updates of the Pod template', 'A dedicated PersistentVolumeClaim per Pod through volumeClaimTemplates'], answer: [0, 3], explain: 'StatefulSets give each replica a <b>sticky identity</b> (name, DNS record via a headless Service) and its <b>own PVC</b> from <code>volumeClaimTemplates</code> that follows it when rescheduled. Both Deployments and StatefulSets support rolling updates, and autoscaling is done by a separate HorizontalPodAutoscaler for either.', ref: 'https://kubernetes.io/docs/concepts/workloads/controllers/statefulset/' },
  { domain: 'fund', q: 'A team needs to run a database schema migration once per release and be sure it completed successfully. Which object fits best?', options: ['Job', 'Deployment with replicas: 1', 'DaemonSet', 'StatefulSet'], answer: 0, explain: 'A <b>Job</b> runs Pods until a given number complete successfully, retrying failures up to backoffLimit. A Deployment would restart the migration container forever after it exits. DaemonSets and StatefulSets are for long-running per-node or stateful services.', ref: 'https://kubernetes.io/docs/concepts/workloads/controllers/job/' },
  { domain: 'fund', q: 'Which object does a CronJob create every time its schedule fires?', options: ['A Pod directly', 'A ReplicaSet', 'A Job', 'A Deployment revision'], answer: 2, explain: 'A <b>CronJob</b> creates a <b>Job</b> on each schedule tick, and that Job creates the Pods. That layering is why Job settings such as backoffLimit and completions live in the CronJob’s <code>jobTemplate</code>. CronJobs never manage ReplicaSets or Deployments.', ref: 'https://kubernetes.io/docs/concepts/workloads/controllers/cron-jobs/' },
  { domain: 'fund', q: 'A Job must process 10 work items and should never run more than 3 Pods at the same time. Which settings achieve this?', options: ['replicas: 10, maxSurge: 3', 'completions: 10, parallelism: 3', 'parallelism: 10, completions: 3', 'backoffLimit: 10, activeDeadlineSeconds: 3'], answer: 1, explain: '<b>completions</b> is how many successful Pods the Job needs; <b>parallelism</b> is how many may run at once. Swapping them would run 10 at once and stop after 3 successes. Jobs have no replicas or maxSurge (Deployment fields); backoffLimit counts retries and activeDeadlineSeconds is a time limit.', ref: 'https://kubernetes.io/docs/concepts/workloads/controllers/job/' },
  { domain: 'fund', q: 'Which TWO <code>restartPolicy</code> values are allowed in the Pod template of a Job? (Select 2)', options: ['Always', 'Never', 'OnFailure', 'IfNotPresent'], answer: [1, 2], explain: 'A Job’s Pods must eventually terminate, so only <b>Never</b> and <b>OnFailure</b> are valid. <code>Always</code> (the Pod default) is rejected for Jobs because the container would restart after succeeding. <code>IfNotPresent</code> is an imagePullPolicy value, not a restart policy.', ref: 'https://kubernetes.io/docs/concepts/workloads/controllers/job/' },

  // ───────────────────────── Core Concepts: ConfigMaps & Secrets ─────────────────────────
  { domain: 'fund', q: 'You update a ConfigMap that a running Deployment consumes through <code>envFrom</code>. What do the running containers see?', options: ['The new values within about a minute', 'The new values only after the container restarts', 'An error, because ConfigMaps in use cannot be modified', 'The new values, and the Pods are automatically rolled'], answer: 1, explain: 'Environment variables are set when the container starts, so they keep the <b>old values until the Pods are restarted</b> (for example with <code>kubectl rollout restart</code>). ConfigMaps mounted as volumes do get refreshed by the kubelet after a short delay (except with subPath). Kubernetes does not block the update and does not roll Pods for you.', ref: 'https://kubernetes.io/docs/concepts/configuration/configmap/' },
  { domain: 'fund', q: 'Which Secret field lets you write values in plain text in the manifest, which the API server then merges into <code>data</code> as base64?', options: ['stringData', 'plainData', 'binaryData', 'immutable'], answer: 0, explain: '<b>stringData</b> is a write-only convenience field; on write its entries are base64-encoded into <code>data</code>. <code>binaryData</code> exists on ConfigMaps for non-UTF-8 content, <code>immutable: true</code> prevents changes, and there is no plainData field.', ref: 'https://kubernetes.io/docs/concepts/configuration/secret/' },
  { domain: 'fund', q: 'A security review finds that Secret values are readable in an etcd backup. Which change protects Secret data stored in etcd?', options: ['Switching Secrets to type kubernetes.io/tls', 'Base64-encoding the values twice', 'Configuring the API server with an EncryptionConfiguration (<code>--encryption-provider-config</code>) for encryption at rest', 'Moving the Secrets to the kube-system namespace'], answer: 2, explain: 'Secrets are only base64-<i>encoded</i> by default. <b>Encryption at rest</b> is enabled on the kube-apiserver through an EncryptionConfiguration (aescbc, secretbox or a KMS provider). Double encoding is still trivially reversible, the Secret type only validates keys, and namespaces control API access, not how etcd stores bytes.', ref: 'https://kubernetes.io/docs/tasks/administer-cluster/encrypt-data/' },
  { domain: 'fund', q: 'A team wants to ship a 200 MB machine-learning model to its Pods in a ConfigMap. Why is this a bad idea?', options: ['ConfigMaps can only be mounted by one Pod at a time', 'ConfigMaps are limited to about 1 MiB of data, so it will be rejected', 'ConfigMaps are deleted when the Pod restarts', 'ConfigMaps can only hold key=value environment variables'], answer: 1, explain: 'ConfigMap (and Secret) data is limited to <b>1 MiB</b> because it is stored in etcd. Large artifacts belong in the image, a PersistentVolume, or object storage. Any number of Pods can mount a ConfigMap, it is not tied to Pod lifetime, and it can hold whole files, not just env vars.', ref: 'https://kubernetes.io/docs/concepts/configuration/configmap/' },

  // ───────────────────────── Core Concepts: labels, selectors, metadata ─────────────────────────
  { domain: 'fund', q: 'What does this command return? <code>kubectl get pods -l app=web,tier!=cache</code>', options: ['Pods labeled app=web whose tier label is not cache, including Pods with no tier label at all', 'Pods labeled app=web or not labeled tier=cache', 'Only Pods that have a tier label with a value other than cache and no app label', 'An error, because != is not supported in label selectors'], answer: 0, explain: 'Comma means <b>AND</b>. The <code>!=</code> equality operator matches objects whose label has a different value <b>or that lack the key</b>. Label selectors support <code>=</code>, <code>==</code>, <code>!=</code> and set-based <code>in</code>, <code>notin</code> and <code>exists</code>; there is no OR across requirements.', ref: 'https://kubernetes.io/docs/concepts/overview/working-with-objects/labels/' },
  { domain: 'fund', q: 'You want to record the git commit and a link to the CI run on each Deployment. Nothing will ever select on these values. Where should they go?', options: ['labels', 'spec.selector', 'status.conditions', 'annotations'], answer: 3, explain: '<b>Annotations</b> hold arbitrary non-identifying metadata (URLs, hashes, tool data) and can be larger than labels. <b>Labels</b> are for identifying and selecting objects and have strict size and character rules. The selector must match Pod labels, and status is written by controllers.', ref: 'https://kubernetes.io/docs/concepts/overview/working-with-objects/annotations/' },
  { domain: 'fund', q: 'Pods are labeled <code>app: frontend</code>. A Service has <code>selector: {app: front-end}</code>. What is the result?', options: ['The Service routes to the Pods because selectors ignore hyphens', 'The Service is rejected by the API server', 'The Service is created but has no endpoints, so connections to it fail', 'kube-proxy fixes the selector automatically'], answer: 2, explain: 'Selectors are exact string matches. The Service is valid, but its <b>EndpointSlices are empty</b> because no Pod matches. A quick check is <code>kubectl get endpointslices -l kubernetes.io/service-name=&lt;svc&gt;</code> or <code>kubectl describe svc</code>. The API server does not validate that anything matches, and nothing auto-corrects labels.', ref: 'https://kubernetes.io/docs/concepts/services-networking/service/' },
  { domain: 'fund', q: 'Which TWO statements about a Deployment’s <code>spec.selector</code> in <code>apps/v1</code> are true? (Select 2)', options: ['It must match the labels in spec.template.metadata.labels', 'It may be omitted and is then copied from the template labels', 'It cannot be changed after the Deployment is created', 'It must include the namespace name as a label'], answer: [0, 2], explain: 'In apps/v1 the selector is <b>required</b>, must <b>match the template labels</b> (otherwise the API rejects the object), and is <b>immutable</b> after creation. Defaulting from the template was old extensions/v1beta1 behaviour, and namespace scoping is implicit, not a label.', ref: 'https://kubernetes.io/docs/concepts/workloads/controllers/deployment/' },

  // ───────────────────────── Core Concepts: extending the API ─────────────────────────
  { domain: 'fund', q: 'Which object lets you add a new resource type such as <code>kind: Database</code> to the Kubernetes API without changing API server code?', options: ['ConfigMap', 'APIService', 'MutatingWebhookConfiguration', 'CustomResourceDefinition'], answer: 3, explain: 'A <b>CustomResourceDefinition (CRD)</b> registers a new kind that the API server stores and serves like a built-in. An APIService is for the heavier aggregation layer (running your own extension API server). Webhooks modify or validate existing requests, and ConfigMaps only hold configuration data.', ref: 'https://kubernetes.io/docs/concepts/extend-kubernetes/api-extension/custom-resources/' },
  { domain: 'fund', q: 'Which description best fits a Kubernetes Operator?', options: ['A custom controller that watches custom resources and encodes the operational knowledge to run an application (install, upgrade, backup, failover)', 'A human administrator with cluster-admin rights', 'A kubectl plugin that formats output', 'A built-in admission controller that enforces quotas'], answer: 0, explain: 'The <b>Operator pattern</b> = CRDs + a controller that reconciles them, automating what a human operator would do. It is software, not a person or a kubectl output tool, and it is unrelated to quota admission.', ref: 'https://kubernetes.io/docs/concepts/extend-kubernetes/operator/' },
  { domain: 'fund', q: 'You install a CRD for <code>kind: Backup</code> but no controller for it, then create a Backup object. What happens?', options: ['The API server rejects the object until a controller registers', 'The object is stored and can be listed, but nothing acts on it', 'The kube-controller-manager runs a generic backup', 'The object is created as a Job automatically'], answer: 1, explain: 'A CRD only teaches the API server to <b>validate and store</b> the new kind. Behaviour comes from a controller (operator) that watches it. Without one, the object just sits in etcd. Nothing built-in interprets custom kinds or converts them to Jobs.', ref: 'https://kubernetes.io/docs/concepts/extend-kubernetes/api-extension/custom-resources/' },

  // ───────────────────────── Administration: kubectl & kubeconfig ─────────────────────────
  { domain: 'fund', q: 'What does <code>kubectl config use-context staging</code> do?', options: ['Creates a new namespace named staging', 'Switches the current context in the kubeconfig so later commands target the cluster, user and namespace of the staging context', 'Copies all objects from the current cluster to staging', 'Logs in to the staging cluster and downloads new certificates'], answer: 1, explain: 'It only changes <b>current-context</b> in your kubeconfig file. A context ties together a cluster, a user and an optional default namespace. It creates nothing in any cluster and does not fetch credentials.', ref: 'https://kubernetes.io/docs/reference/kubectl/generated/kubectl_config/kubectl_config_use-context/' },
  { domain: 'fund', q: 'What does <code>kubectl config set-context --current --namespace=payments</code> do?', options: ['Sets payments as the default namespace for the current context, so later commands without -n use it', 'Creates the payments namespace', 'Moves all Pods into the payments namespace', 'Restricts the current user’s RBAC permissions to the payments namespace'], answer: 0, explain: 'It edits the <b>current context entry</b> in kubeconfig. It is a client-side convenience only: no namespace is created, no objects move (objects cannot change namespace), and RBAC is not affected.', ref: 'https://kubernetes.io/docs/reference/kubectl/generated/kubectl_config/kubectl_config_set-context/' },
  { domain: 'fund', q: 'A kubeconfig file has three main lists. Which are they?', options: ['nodes, pods and services', 'clusters, users and contexts', 'roles, bindings and accounts', 'servers, tokens and namespaces'], answer: 1, explain: 'kubeconfig holds <b>clusters</b> (API server URL and CA), <b>users</b> (credentials) and <b>contexts</b> (a cluster + user + optional namespace), plus <code>current-context</code>. The other options mix in API objects or RBAC concepts that are not kubeconfig sections.', ref: 'https://kubernetes.io/docs/concepts/configuration/organize-cluster-access-kubeconfig/' },
  { domain: 'fund', q: 'Which TWO statements about <code>kubectl apply -f app.yaml</code> are correct? (Select 2)', options: ['It creates the objects if they do not exist and updates them if they do', 'It fails if any object in the file already exists', 'It works only for Deployments and Services', 'It is the declarative approach that is safe to run repeatedly (idempotent)'], answer: [0, 3], explain: '<b>apply</b> is declarative: it reconciles the live object with the file, creating or patching as needed, so you can run it again and again. Failing on existing objects is the behaviour of <code>kubectl create</code>. apply works for any resource type, including CRDs.', ref: 'https://kubernetes.io/docs/tasks/manage-kubernetes-objects/declarative-config/' },
  { domain: 'fund', q: 'What does this command do? <code>kubectl create deployment web --image=nginx --dry-run=client -o yaml &gt; web.yaml</code>', options: ['Creates the Deployment and saves a backup of it to web.yaml', 'Validates web.yaml against the cluster', 'Generates a Deployment manifest locally and writes it to web.yaml without creating anything in the cluster', 'Creates the Deployment in a dry-run namespace'], answer: 2, explain: '<code>--dry-run=client</code> builds the object on the client without sending it, and <code>-o yaml</code> prints it. It is the standard way to <b>scaffold a manifest</b> you then edit and apply. Nothing is created; <code>--dry-run=server</code> would send it for server-side validation but still not persist it.', ref: 'https://kubernetes.io/docs/reference/kubectl/generated/kubectl_create/kubectl_create_deployment/' },
  { domain: 'fund', q: 'What does <code>kubectl explain deployment.spec.strategy</code> show?', options: ['The documentation and type information for that field, taken from the API schema', 'The strategy currently used by every Deployment in the namespace', 'The rollout history of all Deployments', 'Why the last rollout failed'], answer: 0, explain: '<b>kubectl explain</b> prints field documentation from the server’s OpenAPI schema; add <code>--recursive</code> to see nested fields. It reads no live objects. Rollout history is <code>kubectl rollout history</code>, and failure reasons come from describe and events.', ref: 'https://kubernetes.io/docs/reference/kubectl/generated/kubectl_explain/' },
  { domain: 'fund', q: 'A new release of the <code>web</code> Deployment is failing. Which command returns it to the previous revision?', options: ['<code>kubectl rollout pause deployment/web</code>', '<code>kubectl delete rs --all</code>', '<code>kubectl rollout restart deployment/web</code>', '<code>kubectl rollout undo deployment/web</code>'], answer: 3, explain: '<b>rollout undo</b> scales the previous ReplicaSet back up (add <code>--to-revision=N</code> for an older one). <code>pause</code> just freezes the rollout where it is, <code>restart</code> re-creates Pods with the <i>current</i> template, and deleting ReplicaSets throws away the history you need.', ref: 'https://kubernetes.io/docs/reference/kubectl/generated/kubectl_rollout/kubectl_rollout_undo/' },
  { domain: 'fund', q: 'What does <code>kubectl api-resources --namespaced=false</code> list?', options: ['All objects that are not in any namespace right now', 'The resource types that are cluster-scoped, such as nodes, namespaces and persistentvolumes', 'Namespaces that contain no resources', 'API groups that are disabled'], answer: 1, explain: '<b>api-resources</b> lists resource <i>types</i> (with short names, API group and kind). The flag filters to <b>cluster-scoped</b> kinds. It lists no object instances and says nothing about empty namespaces or disabled groups.', ref: 'https://kubernetes.io/docs/reference/kubectl/generated/kubectl_api-resources/' },

  // ───────────────────────── Administration: namespaces & quotas ─────────────────────────
  { domain: 'fund', q: 'Which object sets default CPU and memory requests and limits for containers in a namespace that do not declare their own?', options: ['ResourceQuota', 'PriorityClass', 'LimitRange', 'HorizontalPodAutoscaler'], answer: 2, explain: 'A <b>LimitRange</b> applies per-container (or per-Pod) defaults and min/max values at admission time. A <b>ResourceQuota</b> caps the namespace’s total consumption and object counts, but sets no defaults. PriorityClass affects scheduling order, and HPA changes replica counts.', ref: 'https://kubernetes.io/docs/concepts/policy/limit-range/' },
  { domain: 'fund', q: 'A namespace has a ResourceQuota that limits <code>requests.cpu</code>. There is no LimitRange. A developer applies a Pod without any CPU request. What happens?', options: ['The Pod is created and counted as using 0 CPU', 'The API server rejects the Pod because it must specify a CPU request under that quota', 'The Pod is created but stays Pending forever', 'The quota is ignored for Pods without requests'], answer: 1, explain: 'When a quota tracks a compute resource, <b>every new Pod must specify it</b> or admission rejects it (the error names the missing field). The usual fix is a LimitRange that injects defaults. The Pod never reaches the scheduler, so it is not Pending.', ref: 'https://kubernetes.io/docs/concepts/policy/resource-quotas/' },
  { domain: 'fund', q: 'Which TWO namespaces exist by default in a new Kubernetes cluster? (Select 2)', options: ['kube-system', 'kube-admin', 'kube-node-lease', 'kube-monitoring'], answer: [0, 2], explain: 'A new cluster has <b>default</b>, <b>kube-system</b> (control plane and add-ons), <b>kube-public</b> (readable by all) and <b>kube-node-lease</b> (node heartbeat Lease objects). kube-admin and kube-monitoring are not built-in; monitoring stacks create their own namespaces.', ref: 'https://kubernetes.io/docs/concepts/overview/working-with-objects/namespaces/' },

  // ───────────────────────── Administration: kubeadm, upgrades, maintenance ─────────────────────────
  { domain: 'fund', q: 'Which command adds a new worker node to an existing kubeadm cluster?', options: ['<code>kubeadm join &lt;api-endpoint&gt; --token &lt;token&gt; --discovery-token-ca-cert-hash sha256:&lt;hash&gt;</code>', '<code>kubeadm init --node</code>', '<code>kubectl create node worker3</code>', '<code>kubeadm upgrade node</code>'], answer: 0, explain: '<b>kubeadm join</b>, run on the new machine, uses a bootstrap token and the CA hash to trust the control plane and register the kubelet. <code>kubeadm init</code> creates a new control plane, <code>kubeadm upgrade node</code> upgrades an existing node, and creating a Node object by hand does not install or configure a kubelet.', ref: 'https://kubernetes.io/docs/reference/setup-tools/kubeadm/kubeadm-join/' },
  { domain: 'fund', q: 'You must upgrade a kubeadm cluster from 1.32 to 1.34. What is the supported approach?', options: ['Upgrade all worker kubelets to 1.34 first, then the control plane', 'Upgrade the control plane straight to 1.34 and then the nodes', 'Upgrade one minor version at a time (1.32 → 1.33 → 1.34), upgrading the control plane before the kubelets each time', 'Reinstall the cluster; minor upgrades are not supported in place'], answer: 2, explain: 'kubeadm supports <b>one minor version per upgrade</b>, and the <b>control plane goes first</b> because kubelets must never be newer than the API server. <code>kubeadm upgrade plan</code> shows the available target. In-place upgrades are the normal path; reinstalling is unnecessary.', ref: 'https://kubernetes.io/docs/tasks/administer-cluster/kubeadm/kubeadm-upgrade/' },
  { domain: 'fund', q: 'The kube-apiserver runs version 1.34. Which kubelet version is NOT allowed by the version skew policy?', options: ['1.34', '1.33', '1.31', '1.35'], answer: 3, explain: 'The kubelet may be <b>up to three minor versions older</b> than the API server (1.31 to 1.34 are fine here) but <b>never newer</b>. That is why the control plane is always upgraded first. A 1.35 kubelet against a 1.34 API server is unsupported.', ref: 'https://kubernetes.io/releases/version-skew-policy/' },
  { domain: 'fund', q: 'What does <code>kubectl cordon node2</code> do?', options: ['Evicts all Pods from node2 immediately', 'Marks node2 unschedulable; Pods already running there keep running', 'Removes node2 from the cluster', 'Adds a NoExecute taint that evicts non-tolerating Pods'], answer: 1, explain: '<b>cordon</b> sets <code>spec.unschedulable</code>, so the scheduler places no new Pods there, but existing Pods are untouched. Evicting them is what <b>drain</b> adds on top. Removing the node needs <code>kubectl delete node</code>, and a NoExecute taint is a different mechanism.', ref: 'https://kubernetes.io/docs/reference/kubectl/generated/kubectl_cordon/' },
  { domain: 'fund', q: 'What does <code>kubectl drain node2 --ignore-daemonsets</code> do?', options: ['Cordons node2 and evicts its Pods (respecting PodDisruptionBudgets), leaving DaemonSet-managed Pods in place', 'Deletes all DaemonSets in the cluster', 'Drains only DaemonSet Pods from node2', 'Shuts down the kubelet on node2'], answer: 0, explain: '<b>drain</b> = cordon + evict through the Eviction API, so PDBs are honoured. DaemonSet Pods would be recreated on the same node anyway, so drain refuses to continue unless you pass <code>--ignore-daemonsets</code>, which skips them. It never deletes DaemonSets or stops the kubelet; afterwards you run <code>kubectl uncordon</code>.', ref: 'https://kubernetes.io/docs/tasks/administer-cluster/safely-drain-node/' },
  { domain: 'fund', q: '<code>kubectl drain</code> keeps retrying with “Cannot evict pod as it would violate the pod’s disruption budget”. What is the most likely situation?', options: ['The node has a NoSchedule taint', 'The Pods use emptyDir volumes', 'The kubelet on the node is down', 'A PodDisruptionBudget requires more Pods to stay available than would remain if this Pod were evicted'], answer: 3, explain: 'Eviction checks <b>PodDisruptionBudgets</b>. If minAvailable/maxUnavailable would be violated (often a PDB covering a single-replica app), the eviction is refused and drain retries. Fix it by scaling up or adjusting the PDB. emptyDir Pods need <code>--delete-emptydir-data</code> but give a different error, and taints do not block eviction.', ref: 'https://kubernetes.io/docs/tasks/administer-cluster/safely-drain-node/' },
  { domain: 'fund', q: 'Which command takes a backup of etcd?', options: ['<code>kubectl get all -A -o yaml &gt; backup.yaml</code>', '<code>kubeadm backup etcd</code>', '<code>kubectl cp etcd-0:/var/lib/etcd ./backup</code>', '<code>etcdctl snapshot save backup.db</code> (with the endpoint and TLS certificate flags)'], answer: 3, explain: '<b>etcdctl snapshot save</b> creates a consistent point-in-time snapshot of the keyspace; restore it with <code>etcdutl snapshot restore</code> (older guides use etcdctl). <code>kubectl get all</code> covers only a few resource types and is not a consistent store snapshot; kubeadm has no backup subcommand; copying the data directory of a live member is not a consistent backup.', ref: 'https://kubernetes.io/docs/tasks/administer-cluster/configure-upgrade-etcd/' },

  // ───────────────────────── Scheduling: nodeSelector & node affinity ─────────────────────────
  { domain: 'fund', q: 'What is the simplest way to make sure a Pod is only scheduled on nodes labeled <code>disktype=ssd</code>?', options: ['Add <code>nodeSelector: {disktype: ssd}</code> to the Pod spec', 'Taint the SSD nodes with disktype=ssd:NoSchedule', 'Add a toleration for disktype=ssd', 'Create a PriorityClass named ssd'], answer: 0, explain: '<b>nodeSelector</b> is the simplest hard constraint: the node must have every listed label. Tainting SSD nodes would <i>repel</i> other Pods, and a toleration only <i>permits</i> scheduling onto tainted nodes without attracting the Pod. PriorityClasses have nothing to do with node choice.', ref: 'https://kubernetes.io/docs/concepts/scheduling-eviction/assign-pod-node/' },
  { domain: 'fund', q: 'A Pod was scheduled using <code>requiredDuringSchedulingIgnoredDuringExecution</code> node affinity for <code>zone=a</code>. Later, an admin removes that label from the node. What happens to the running Pod?', options: ['It is evicted immediately', 'It keeps running; the rule is only checked at scheduling time', 'It is restarted on the same node', 'It becomes Pending until the label is restored'], answer: 1, explain: '<b>IgnoredDuringExecution</b> means label changes after binding do not affect Pods already running. Only new scheduling decisions use the rule. If you need running Pods pushed off a node, use a <b>NoExecute taint</b> instead.', ref: 'https://kubernetes.io/docs/concepts/scheduling-eviction/assign-pod-node/' },
  { domain: 'fund', q: 'You want Pods to land in zone <code>eu-west-1a</code> when possible, but still run elsewhere if that zone is full. What should you use?', options: ['nodeSelector with the zone label', 'requiredDuringSchedulingIgnoredDuringExecution node affinity', 'A NoSchedule taint on the other zones', 'preferredDuringSchedulingIgnoredDuringExecution node affinity with a weight'], answer: 3, explain: '<b>preferred…</b> rules are <b>soft</b>: they add score (weight 1–100) to matching nodes but never block scheduling. nodeSelector and required affinity are hard constraints that leave Pods Pending if unmet, and tainting other zones would also block them.', ref: 'https://kubernetes.io/docs/concepts/scheduling-eviction/assign-pod-node/' },
  { domain: 'fund', q: 'Which TWO things can node affinity express that a plain nodeSelector cannot? (Select 2)', options: ['Repelling every Pod that does not explicitly opt in', 'Operators such as NotIn, Exists and Gt', 'Placing a Pod next to other Pods with a given label', 'Soft preferences with weights'], answer: [1, 3], explain: 'Node affinity adds <b>set-based operators</b> (In, NotIn, Exists, DoesNotExist, Gt, Lt) and <b>preferred (soft) rules</b>. Repelling Pods by default is what <b>taints</b> do, and co-locating with other Pods is <b>pod affinity</b>, which looks at Pod labels rather than node labels.', ref: 'https://kubernetes.io/docs/concepts/scheduling-eviction/assign-pod-node/' },

  // ───────────────────────── Scheduling: pod affinity & anti-affinity ─────────────────────────
  { domain: 'fund', q: 'You want the replicas of a Deployment to run on different nodes, so a single node failure cannot take them all down. Which rule expresses this directly?', options: ['nodeSelector with kubernetes.io/hostname', 'podAffinity with topologyKey topology.kubernetes.io/zone', 'podAntiAffinity matching the app’s own label, with topologyKey kubernetes.io/hostname', 'A toleration for node.kubernetes.io/unreachable'], answer: 2, explain: '<b>Pod anti-affinity</b> against the app’s own label with <code>topologyKey: kubernetes.io/hostname</code> keeps replicas off nodes that already run one. podAffinity would pull them <i>together</i>; nodeSelector on hostname pins to one node; the toleration only controls how long Pods stay on an unreachable node. (Topology spread constraints are the other common answer.)', ref: 'https://kubernetes.io/docs/concepts/scheduling-eviction/assign-pod-node/' },
  { domain: 'fund', q: 'A cache Pod should run in the same availability zone as the web Pods that use it (any node in that zone is fine). Which configuration fits?', options: ['podAffinity selecting app=web with topologyKey topology.kubernetes.io/zone', 'podAntiAffinity selecting app=web with topologyKey kubernetes.io/hostname', 'nodeAffinity on the label app=web', 'A taint app=web:NoSchedule on the web nodes'], answer: 0, explain: '<b>podAffinity</b> attracts the Pod to topology domains that already hold matching Pods, and the <b>topologyKey</b> defines the domain, here the zone. Anti-affinity does the opposite, and nodeAffinity matches <i>node</i> labels, not Pod labels. A taint would keep the cache away.', ref: 'https://kubernetes.io/docs/concepts/scheduling-eviction/assign-pod-node/' },
  { domain: 'fund', q: 'A Deployment with 4 replicas uses required pod anti-affinity on its own label with <code>topologyKey: kubernetes.io/hostname</code>. The cluster has 3 schedulable worker nodes. What do you observe?', options: ['4 Running Pods, two of them on the same node', 'The Deployment is rejected by the API server', 'All 4 Pods stay Pending', '3 Running Pods, one per node, and 1 Pod Pending'], answer: 3, explain: 'A <b>required</b> anti-affinity rule allows at most one replica per hostname, so the fourth Pod has nowhere to go and stays <b>Pending</b> (FailedScheduling: didn’t match pod anti-affinity rules). The other three are unaffected. A <i>preferred</i> rule would have let the fourth double up. The API server does not check schedulability.', ref: 'https://kubernetes.io/docs/concepts/scheduling-eviction/assign-pod-node/' },

  // ───────────────────────── Scheduling: taints & tolerations ─────────────────────────
  { domain: 'fund', q: 'What does <code>kubectl taint nodes gpu1 hardware=gpu:NoSchedule</code> do?', options: ['Evicts every Pod currently running on gpu1', 'Labels gpu1 so that Pods with nodeSelector hardware=gpu go there', 'Prevents new Pods without a matching toleration from being scheduled on gpu1; existing Pods stay', 'Reserves gpu1 for Pods in the hardware namespace'], answer: 2, explain: 'A <b>NoSchedule</b> taint blocks new non-tolerating Pods but leaves running Pods alone (that would need <b>NoExecute</b>). Taints are not labels, so nodeSelector does not see them, and taints have no notion of namespaces.', ref: 'https://kubernetes.io/docs/concepts/scheduling-eviction/taint-and-toleration/' },
  { domain: 'fund', q: 'Which taint effect also evicts Pods already running on the node if they do not tolerate it?', options: ['NoExecute', 'NoSchedule', 'PreferNoSchedule', 'Unschedulable'], answer: 0, explain: '<b>NoExecute</b> blocks scheduling and evicts running non-tolerating Pods (optionally after <code>tolerationSeconds</code>). NoSchedule only affects new Pods and PreferNoSchedule is a soft version of it. “Unschedulable” is the cordon field, not a taint effect.', ref: 'https://kubernetes.io/docs/concepts/scheduling-eviction/taint-and-toleration/' },
  { domain: 'fund', q: 'A Pod tolerates the taint on the GPU nodes, yet it was scheduled onto an ordinary node. Why?', options: ['The toleration must also be added to the node', 'The scheduler ignores tolerations for Deployments', 'The GPU nodes must be cordoned for the toleration to take effect', 'A toleration only allows the Pod onto tainted nodes; it does not attract it. Add node affinity or a nodeSelector to require GPU nodes'], answer: 3, explain: 'Taints and tolerations are a <b>repel/permit</b> mechanism. To <b>dedicate</b> nodes you combine a taint (keeps others out) with node affinity or nodeSelector (pulls your Pods in). Nodes do not carry tolerations, Deployments are not special, and cordoning would block all new Pods.', ref: 'https://kubernetes.io/docs/concepts/scheduling-eviction/taint-and-toleration/' },
  { domain: 'fund', q: 'Why do ordinary workload Pods not get scheduled onto control plane nodes in a default kubeadm cluster?', options: ['The kubelet on control plane nodes is disabled', 'Control plane nodes carry the taint <code>node-role.kubernetes.io/control-plane:NoSchedule</code>', 'Control plane nodes have no container runtime', 'The scheduler is hard-coded to skip nodes in kube-system'], answer: 1, explain: 'kubeadm adds a <b>NoSchedule taint</b> to control plane nodes. Pods that tolerate it (some system DaemonSets) still run there, and removing the taint lets anything schedule there (common on single-node clusters). Control plane nodes do run a kubelet and runtime for the static Pods, and nodes do not belong to namespaces.', ref: 'https://kubernetes.io/docs/setup/production-environment/tools/kubeadm/create-cluster-kubeadm/' },
  { domain: 'fund', q: 'What does the trailing minus do in <code>kubectl taint nodes node1 dedicated=db:NoSchedule-</code>?', options: ['Lowers the taint to PreferNoSchedule', 'Applies the taint to every node except node1', 'Removes that taint from node1', 'Marks the taint as temporary'], answer: 2, explain: 'A trailing <b>-</b> <b>removes</b> the taint (the same convention removes labels: <code>kubectl label node node1 disktype-</code>). There is no syntax for downgrading, inverting the target, or temporary taints; time limits are expressed with <code>tolerationSeconds</code> on the Pod side for NoExecute.', ref: 'https://kubernetes.io/docs/concepts/scheduling-eviction/taint-and-toleration/' },

  // ───────────────────────── Scheduling: topology spread, priority, scheduler internals ─────────────────────────
  { domain: 'fund', q: 'You want the Pods of a Deployment spread evenly across zones, with the Pod count in any two zones differing by at most one. Which field is designed for this?', options: ['affinity.podAffinity', 'spec.nodeName', 'A PodDisruptionBudget with maxUnavailable: 1', 'topologySpreadConstraints with maxSkew: 1 and topologyKey: topology.kubernetes.io/zone'], answer: 3, explain: '<b>topologySpreadConstraints</b> control how unevenly matching Pods may be distributed (<b>maxSkew</b>) across domains defined by <b>topologyKey</b>. Pod affinity groups Pods together; nodeName pins to one node; a PDB limits voluntary disruptions and does not influence placement.', ref: 'https://kubernetes.io/docs/concepts/scheduling-eviction/topology-spread-constraints/' },
  { domain: 'fund', q: 'In a topology spread constraint, what does <code>whenUnsatisfiable: ScheduleAnyway</code> mean?', options: ['The Pod stays Pending until the skew can be satisfied', 'The scheduler still places the Pod, using the constraint only to prefer nodes that reduce skew', 'The constraint is ignored entirely', 'Existing Pods are evicted to rebalance the zones'], answer: 1, explain: '<b>ScheduleAnyway</b> turns the constraint into a soft scoring preference; <b>DoNotSchedule</b> (the default) is the hard version that leaves the Pod Pending. The scheduler never evicts running Pods to fix skew (that would be the separate Descheduler project).', ref: 'https://kubernetes.io/docs/concepts/scheduling-eviction/topology-spread-constraints/' },
  { domain: 'fund', q: 'A high-priority Pod is Pending because the cluster is full. What may kube-scheduler do?', options: ['Add a new node to the cluster', 'Lower the Pod’s resource requests until it fits', 'Preempt (evict) lower-priority Pods on a node so the high-priority Pod can be scheduled there', 'Merge the Pod into an existing Pod'], answer: 2, explain: 'With <b>PriorityClasses</b>, the scheduler can <b>preempt</b> lower-priority Pods to make room. Adding nodes is the Cluster Autoscaler’s job, and changing requests is what a VPA would do; the scheduler does neither.', ref: 'https://kubernetes.io/docs/concepts/scheduling-eviction/pod-priority-preemption/' },
  { domain: 'fund', q: 'Which TWO statements about PriorityClass are correct? (Select 2)', options: ['A higher value means higher priority', 'PriorityClass is a namespaced object', 'Pods reference it through spec.priorityClassName', 'Pods with a lower value can preempt Pods with a higher value'], answer: [0, 2], explain: 'A <b>PriorityClass</b> is a <b>cluster-scoped</b> object mapping a name to an integer <b>value</b>; higher wins. Pods use it via <b>priorityClassName</b>, and only higher-priority Pods preempt lower ones, never the reverse.', ref: 'https://kubernetes.io/docs/concepts/scheduling-eviction/pod-priority-preemption/' },
  { domain: 'fund', q: 'A Pod is Pending with the event <code>0/3 nodes are available: 3 Insufficient cpu</code>. Monitoring shows all nodes at about 20% actual CPU usage. What explains this?', options: ['The scheduler compares the Pod’s CPU request with node allocatable minus the requests of Pods already placed, not with actual usage', 'Metrics are wrong; the nodes must really be at 100%', 'The Pod’s CPU limit is lower than its request', 'The kubelet is throttling the scheduler'], answer: 0, explain: 'Scheduling is based on <b>requests</b>, not live usage. If existing Pods have reserved most allocatable CPU through requests, a new Pod cannot fit even when the nodes are mostly idle. Fixes: lower over-sized requests, add nodes, or use preemption. A limit below the request is rejected at admission, and kubelets do not throttle the scheduler.', ref: 'https://kubernetes.io/docs/concepts/configuration/manage-resources-containers/' },
  { domain: 'fund', q: 'A Pod is Pending with: <code>0/2 nodes are available: 2 node(s) had untolerated taint {dedicated: db}</code>. Which change lets it schedule?', options: ['Add a nodeSelector for dedicated=db', 'Increase the Pod’s priority', 'Restart the kubelets', 'Add a toleration for dedicated=db with the matching effect (or remove the taint)'], answer: 3, explain: 'The message says every node carries a <b>taint the Pod does not tolerate</b>. Adding a matching <b>toleration</b> (or removing the taint) is the fix. A nodeSelector would not bypass a taint, priority only matters for preemption among Pods, and kubelet restarts do not change taints.', ref: 'https://kubernetes.io/docs/concepts/scheduling-eviction/taint-and-toleration/' },
  { domain: 'fund', q: 'In which order does kube-scheduler place a Pod?', options: ['Score all nodes, bind, then filter', 'Filter out nodes that cannot run the Pod, score the remaining nodes, then bind the Pod to the best one', 'Bind to a random node, then move it if a filter fails', 'Ask each kubelet to bid for the Pod'], answer: 1, explain: 'The scheduling cycle is <b>filtering</b> (resources, taints, affinity, node selectors) then <b>scoring</b> the feasible nodes, followed by <b>binding</b> (writing <code>spec.nodeName</code>). Pods are never moved after binding, and kubelets do not bid.', ref: 'https://kubernetes.io/docs/concepts/scheduling-eviction/kube-scheduler/' },
  { domain: 'fund', q: 'A Pod manifest sets <code>spec.nodeName: worker2</code> directly. What is true?', options: ['The scheduler still filters and may override it', 'The Pod is rejected unless it also has a toleration', 'The scheduler is bypassed; the kubelet on worker2 runs the Pod directly, so scheduler-only checks like affinity are skipped', 'nodeName is only a soft preference'], answer: 2, explain: 'Setting <b>nodeName</b> is a manual binding, so <b>kube-scheduler skips the Pod</b>. The kubelet still rejects it if resources are insufficient or a NoExecute taint applies. It is not a preference and cannot be overridden by the scheduler.', ref: 'https://kubernetes.io/docs/concepts/scheduling-eviction/assign-pod-node/' },

  // ───────────────────────── Containerization: images & Dockerfiles ─────────────────────────
  { domain: 'fund', q: 'Why do Dockerfiles usually copy the dependency manifest and install dependencies <i>before</i> copying the application source code?', options: ['Layers are built in parallel, so order does not matter for speed', 'So a code change only invalidates the later layers and the cached dependency layer is reused', 'Because COPY must always be the last instruction', 'To make the final image use fewer CPU cycles at runtime'], answer: 1, explain: 'Images are built as ordered <b>layers</b>, and the build cache is reused until an instruction’s inputs change. Putting rarely changing steps first keeps the expensive dependency layer <b>cached</b> across code edits. Layers build sequentially, COPY may appear anywhere, and layer order does not change runtime CPU use.', ref: 'https://docs.docker.com/build/building/best-practices/' },
  { domain: 'fund', q: 'What is the main benefit of a multi-stage Dockerfile build?', options: ['It runs several containers from one image', 'It lets one image run on multiple CPU architectures at once', 'It encrypts the layers of the final image', 'Build tools and intermediate files stay in earlier stages, so the final image is smaller and has less attack surface'], answer: 3, explain: 'With <b>multi-stage builds</b> you compile in a full toolchain stage and <code>COPY --from</code> only the artifacts into a slim final stage. Multi-arch images are a separate manifest-list feature, images are not encrypted by this, and one image still runs one container per instance.', ref: 'https://docs.docker.com/build/building/multi-stage/' },
  { domain: 'fund', q: 'A Dockerfile has <code>ENTRYPOINT ["python","app.py"]</code> and <code>CMD ["--port","80"]</code>. A Pod sets <code>args: ["--port","8080"]</code> and no <code>command</code>. What runs?', options: ['<code>--port 8080</code> on its own', '<code>python app.py --port 80 --port 8080</code>', '<code>python app.py --port 8080</code>', 'The container fails because command is missing'], answer: 2, explain: 'In Kubernetes, <b>command overrides ENTRYPOINT</b> and <b>args overrides CMD</b>. Setting only args keeps the image’s entrypoint and replaces its default arguments. Args are not appended to CMD, and command is optional.', ref: 'https://kubernetes.io/docs/tasks/inject-data-application/define-command-argument-container/' },
  { domain: 'fund', q: 'Why would you reference an image as <code>registry.example.com/web@sha256:3f1c…</code> instead of <code>web:1.4</code>?', options: ['A digest is immutable, so every node runs exactly the same image content even if the tag is moved', 'Digests download faster than tags', 'Digest references skip image signature checks', 'Kubernetes only caches images referenced by digest'], answer: 0, explain: 'Tags are mutable pointers; a <b>digest</b> is the content hash of the image manifest, so it always identifies the same bytes. That gives reproducible, tamper-evident deployments. Download speed and caching are the same, and digests do not disable signature verification.', ref: 'https://kubernetes.io/docs/concepts/containers/images/' },

  // ───────────────────────── Containerization: pulling images ─────────────────────────
  { domain: 'fund', q: 'A container uses <code>image: nginx</code> (no tag) and sets no <code>imagePullPolicy</code>. Which policy applies?', options: ['IfNotPresent', 'Never', 'OnFailure', 'Always'], answer: 3, explain: 'With no tag the image resolves to <code>:latest</code>, and for <code>:latest</code> (or no tag) the default policy is <b>Always</b>. Any other tag or a digest defaults to <b>IfNotPresent</b>. Never only uses images already on the node, and OnFailure is a restartPolicy value.', ref: 'https://kubernetes.io/docs/concepts/containers/images/' },
  { domain: 'fund', q: 'Pods pulling from a private registry are stuck in <code>ImagePullBackOff</code> with an authentication error. Which Pod field should reference the registry credentials?', options: ['<code>securityContext</code>', '<code>envFrom</code>', '<code>imagePullSecrets</code>', '<code>serviceAccountName</code> with automountServiceAccountToken: true'], answer: 2, explain: '<b>imagePullSecrets</b> points to a Secret of type <code>kubernetes.io/dockerconfigjson</code> that the kubelet uses to authenticate to the registry (you can also attach it to the ServiceAccount). Env vars and securityContext do not reach the image pull, and the ServiceAccount token authenticates to the Kubernetes API, not the registry.', ref: 'https://kubernetes.io/docs/tasks/configure-pod-container/pull-image-private-registry/' },

  // ───────────────────────── Containerization: runtimes, OCI, CRI ─────────────────────────
  { domain: 'fund', q: 'Which TWO are specifications published by the Open Container Initiative (OCI)? (Select 2)', options: ['Container Network Interface', 'Runtime Specification', 'Image Specification', 'Container Runtime Interface'], answer: [1, 2], explain: 'OCI defines the <b>Runtime Spec</b> (how to run a container bundle), the <b>Image Spec</b> (image format) and the Distribution Spec (registry API). <b>CNI</b> is a CNCF project for Pod networking, and <b>CRI</b> is a Kubernetes API between the kubelet and runtimes.', ref: 'https://opencontainers.org/' },
  { domain: 'fund', q: 'Which component is a low-level OCI runtime that actually creates the container process with Linux namespaces and cgroups?', options: ['containerd', 'kubelet', 'CRI-O', 'runc'], answer: 3, explain: '<b>runc</b> is the reference low-level runtime implementing the OCI Runtime Spec. <b>containerd</b> and <b>CRI-O</b> are high-level runtimes that pull images, manage storage and expose CRI, then call runc (or another OCI runtime). The kubelet talks to them through CRI and never creates processes itself.', ref: 'https://github.com/opencontainers/runc' },
  { domain: 'fund', q: 'A cluster upgraded to Kubernetes 1.24 or later used Docker Engine through dockershim. What is true?', options: ['Images built with docker build stop working and must be rebuilt', 'Kubernetes now only supports Podman', 'The nodes need a CRI-compatible runtime such as containerd or CRI-O (or the external cri-dockerd adapter); existing OCI images keep working', 'dockershim must be enabled with a feature gate'], answer: 2, explain: '<b>dockershim was removed in 1.24</b>, so the kubelet needs a <b>CRI</b> runtime. Docker-built images are standard <b>OCI images</b> and run unchanged on containerd or CRI-O. Mirantis’ cri-dockerd exists for those who must keep Docker Engine. There is no feature gate to bring dockershim back, and Podman is not a CRI runtime.', ref: 'https://kubernetes.io/docs/tasks/administer-cluster/migrating-from-dockershim/check-if-dockershim-removal-affects-you/' },
  { domain: 'fund', q: 'Which container runtime was built specifically to implement the Kubernetes CRI and nothing else?', options: ['CRI-O', 'Docker Engine', 'runc', 'Podman'], answer: 0, explain: '<b>CRI-O</b> is a lightweight runtime whose only purpose is serving the kubelet over CRI. Docker Engine and Podman are general-purpose tools for developers, and runc is a low-level OCI runtime with no CRI API.', ref: 'https://cri-o.io/' },
  { domain: 'fund', q: 'Untrusted workloads must run in a sandboxed runtime such as gVisor or Kata Containers, while all other Pods keep the default runtime. How is this selected per Pod?', options: ['Set imagePullPolicy: Sandbox', 'Create a RuntimeClass for the handler and set <code>spec.runtimeClassName</code> in those Pods', 'Use a separate kubeconfig context', 'Add a CNI plugin for sandboxing'], answer: 1, explain: 'A <b>RuntimeClass</b> maps a name to a runtime handler configured on the nodes; Pods opt in with <b>runtimeClassName</b>. imagePullPolicy only controls pulls, kubeconfig contexts are client-side, and CNI handles networking, not process isolation.', ref: 'https://kubernetes.io/docs/concepts/containers/runtime-class/' },
  { domain: 'fund', q: 'Which Linux kernel feature does a container runtime use to limit how much CPU and memory a container can consume?', options: ['Namespaces', 'Control groups (cgroups)', 'chroot', 'SELinux labels'], answer: 1, explain: '<b>cgroups</b> account for and limit resources, which is how CPU and memory limits are enforced. <b>Namespaces</b> isolate what a process can <i>see</i> (PIDs, network, mounts); chroot only changes the root directory; SELinux is mandatory access control, not resource limiting.', ref: 'https://kubernetes.io/docs/concepts/architecture/cgroups/' },
]);
